function construct(Ctor, args) {
  return Reflect.construct(Ctor, args);
}

function flatten(input) {
  const result = [];
  for (const item of input) {
    if (Array.isArray(item)) result.push(...flatten(item));
    else result.push(item);
  }
  return result;
}

function promisifyOne(fn) {
  return function (...args) {
    // 普通函数保留调用接收者；箭头包装会意外捕获创建时的 this。
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (err, value) => {
        if (err) reject(err);
        else resolve(value);
      });
    });
  };
}

function reverseDense(array) {
  // 只接收普通稠密可写数组，避免把空槽与 undefined 当作同一语义。
  for (let left = 0, right = array.length - 1; left < right; left++, right--) {
    const value = array[left];
    array[left] = array[right];
    array[right] = value;
  }
  return array;
}

function listToTree(list, { idKey = 'id', parentKey = 'parent_id' } = {}) {
  const nodes = new Map();
  for (const item of list) {
    if (nodes.has(item[idKey])) throw new Error(`重复 id: ${item[idKey]}`);
    nodes.set(item[idKey], { ...item, children: [] });
  }
  const roots = [];
  const orphans = [];
  for (const item of list) {
    const node = nodes.get(item[idKey]);
    const parentId = item[parentKey];
    if (parentId === null || parentId === undefined) { roots.push(node); continue; }
    const parent = nodes.get(parentId);
    if (parent) parent.children.push(node);
    else orphans.push(node); // 父节点缺失
  }
  // 环检测：从 roots 出发的 DFS 覆盖不到、又不属于孤儿的节点即为环的一部分
  const seen = new Set();
  const stack = [...roots];
  while (stack.length) {
    const node = stack.pop();
    if (seen.has(node[idKey])) continue;
    seen.add(node[idKey]);
    stack.push(...node.children);
  }
  const cyclic = [...nodes.values()].filter(n => !seen.has(n[idKey]) && !orphans.includes(n));
  return { roots, orphans, cyclic };
}
